draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character 1
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 + 20, H/2 + 40);
  ctx.stroke();

  // character 2
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 + 20, H/2 + 40);
  ctx.stroke();

  // empathy line
  ctx.beginPath();
  ctx.moveTo(W/4 + 20, H/2 + 40);
  ctx.lineTo(W - W/4 - 20, H/2 + 40);
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // pulsing empathy line
  ctx.beginPath();
  ctx.moveTo(W/4 + 20 + Math.sin(t) * 10, H/2 + 40);
  ctx.lineTo(W - W/4 - 20 + Math.sin(t) * 10, H/2 + 40);
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  ctx.restore();
}
